def post(request):
    if request['method'] == 'GET':
        return 'show the empty form'
    if request['method'] == 'POST':
        content = request['form']['content']
        return f'received {len(content.split())} words'

print(post({'method': 'GET'}))
print(post({'method': 'POST', 'form': {'content': 'Python is fun'}}))

